r=Path('/home/cat/projects/RK3576/rk3576_multimodal_stage5_review');p=r/'reports/stage5_04_board/profile_tool_setup';p.mkdir()
old=r/'tools/stage5_04_run.py';assert hashlib.sha256(old.read_bytes()).hexdigest()==OLD_RUNNER;shutil.copyfile(old,p/'run_before.py')
for row in ROWS:
 target=r/row['file'] if row['file'].startswith('tools/') else p/'vision_bench.cpp'
 if target!=old:assert not target.exists()
 data=base64.b64decode(row['data']);assert hashlib.sha256(data).hexdigest()==row['sha256'];target.write_bytes(data)
(p/'installed_manifest.json').write_text(json.dumps([{k:v for k,v in x.items() if k!='data'} for x in ROWS],indent=2))
config='source "$1/tools/stage5_board_paths.sh"; exec g++ -std=c++17 -O3 -Wall -Wextra -Wpedantic -I"$1/stage5_04_baseline_source/include" "$2/vision_bench.cpp" "$1/build/stage5_04_baseline/libmultimodal_core.a" "$STAGE5_RKNN_LIBRARY" "$STAGE5_RKLLM_LIB/librkllmrt.so" -pthread -o "$2/vision_bench"'
