with (p/'build.stdout.log').open('wb') as o,(p/'build.stderr.log').open('wb') as e:code=subprocess.run(cmd,stdout=o,stderr=e,timeout=120).returncode
(p/'result.json').write_text(json.dumps({'returncode':code,'diagnostic_links_frozen_instrumented_baseline':True}));print('TOOL_SETUP',code,flush=True)
